from modele import chapitre,E,Q

chapitre(16,'translations','Translations, agrandissements et réductions','4 · Géométrie et espace',
'Glissement · Frises · Longueurs · Aires · Volumes',
['Construire l’image d’une figure par translation.','Utiliser les propriétés de conservation.','Relier un rapport de longueurs aux aires et aux volumes.'],
['Repérage, parallélogrammes et proportionnalité.'],[
r'''\essSection{1}{Faire glisser une figure}
\begin{definition}Une translation fait glisser une figure selon une même direction, un même sens et une même longueur, sans la faire tourner. La translation qui transforme P en Q applique ce même déplacement à chaque point de la figure.\end{definition}
@FIG:cours-translation@
\begin{propriete}Une translation conserve les longueurs, les angles, l’alignement, le parallélisme et les aires. Un segment et son image sont parallèles et de même longueur. Si A a pour image A’ et B pour image B’, le quadrilatère A-B-B’-A’ est un parallélogramme quand ses sommets sont distincts et non alignés.\end{propriete}
\begin{savoirfaire}[Construire]Sur quadrillage, compter le déplacement de P vers Q et le reproduire depuis chaque sommet. Sans quadrillage, construire les parallèles et reporter la même longueur dans le même sens. Une frise ou un pavage peut répéter un motif par translations.\end{savoirfaire}''',
r'''\essSection{2}{Changer de taille}
\begin{definition}Un agrandissement ou une réduction multiplie toutes les longueurs correspondantes par un même rapport positif $k$. Si $k>1$, c’est un agrandissement ; si $0<k<1$, une réduction. Les angles sont conservés.\end{definition}
\begin{propriete}Quand les longueurs sont multipliées par $k$, les périmètres sont multipliés par $k$, les aires par $k^2$ et les volumes par $k^3$. On peut retrouver ces facteurs en appliquant les formules d’aire et de volume aux nouvelles dimensions.\end{propriete}
\begin{exemple}Pour un rectangle de 6 cm sur 4 cm agrandi avec $k=1{,}5$, les côtés deviennent 9 et 6 cm. L’aire passe de 24 à 54 cm$^2$ : elle est multipliée par $1{,}5^2=2{,}25$. Pour un cube réduit de moitié, le volume est divisé par 8.\end{exemple}
\begin{attention}Une translation conserve la taille, contrairement à un agrandissement. Pour retrouver $k$ depuis les aires, on cherche le nombre positif dont le carré est le rapport des aires ; le rapport des aires n’est pas directement le rapport des longueurs.\end{attention}'''],[
E('Décrire le glissement',r"Dans le quadrillage, la translation transforme P(0;0) en Q(3;1). Quelle est l’image de A(1;2) ?",r"Le déplacement ajoute 3 à l’abscisse et 1 à l’ordonnée. L’image est donc $\res{A'(4;3)}$. Le même comptage s’applique à chaque point.","Reproduire le déplacement horizontal et vertical.","assert (1+3,2+1)==(4,3)",figure='trans-01'),
E('Construire un triangle image',r"Construire l’image de $A(1;1)$, $B(3;1)$, $C(2;3)$ par le glissement de 3 carreaux à droite et 2 vers le haut.",r"On obtient $\res{A'(4;3),\ B'(6;3),\ C'(5;5)}$. Placer les trois images, puis relier dans le même ordre. Les côtés correspondants restent parallèles et de même longueur.","Appliquer le même déplacement aux trois sommets.","assert [(a+3,b+2) for a,b in [(1,1),(3,1),(2,3)]]==[(4,3),(6,3),(5,5)]",figure='trans-02'),
E('Un déplacement négatif',r"Une translation déplace de 4 carreaux vers la gauche et 1 vers le bas. Donner l’image de B(2;3).",r"Vers la gauche, on soustrait 4 à l’abscisse ; vers le bas, on soustrait 1 à l’ordonnée. Donc $\res{B'(-2;2)}$.","Relier le sens du déplacement au signe du calcul.","assert (2-4,3-1)==(-2,2)",figure='trans-03'),
E('Conserver des mesures',r"ABC a $AB=5$ cm, $\widehat{BAC}=42^\circ$ et une aire de 9 cm$^2$. Donner ces mesures dans son image A’B’C’ par translation.",r"Une translation conserve longueurs, angles et aires. Donc $\res{A'B'=5\ \mathrm{cm}}$, $\res{\widehat{B'A'C'}=42^\circ}$ et l’aire image vaut $\res{9\ \mathrm{cm}^2}$.","Citer la conservation adaptée à chaque mesure.","assert 5==5 and 42==42 and 9==9",figure='trans-04'),
E('Reconnaître une frise',r"Les débuts de cinq motifs identiques d’une frise sont espacés de 4 cm. Quel glissement mène du premier au suivant ? Du premier au cinquième ?",r"Du premier au suivant : translation de 4 cm vers la droite. Du premier au cinquième, on compte quatre intervalles : $4\times4=\res{16}$ cm. Cinq motifs ne font pas cinq écarts.","Compter les intervalles entre les motifs.","assert (5-1)*4==16",figure='trans-05'),
E('Un parallélogramme',r"A a pour image A’ et B pour image B’ par une même translation. Les quatre points sont non alignés et distincts. Justifier que A-B-B’-A’ est un parallélogramme.",r"Les segments AB et A’B’ sont parallèles et de même longueur, car ils sont images par translation. Dans l’ordre A-B-B’-A’, ce sont deux côtés opposés. Un quadrilatère ayant deux côtés opposés parallèles et de même longueur est un parallélogramme.","Respecter l’ordre des sommets du quadrilatère.","assert (1+3,1+2)==(4,3) and (4+3,1+2)==(7,3)",figure='trans-06'),
E('Agrandir une figure',r"Un rectangle de 6 cm sur 4 cm est agrandi avec un rapport de 1,5. Donner ses dimensions et son périmètre.",r"Les dimensions deviennent $6\times1{,}5=\res9$ cm et $4\times1{,}5=\res6$ cm. Le périmètre vaut $2(9+6)=\res{30}$ cm, soit 1,5 fois le périmètre initial 20 cm.","Multiplier toutes les longueurs par le même rapport.","assert 6*Rational('1.5')==9 and 4*Rational('1.5')==6 and 2*(9+6)==30",figure='trans-07'),
E('Réduire un triangle',r"Un triangle de côtés 5, 7 et 8 cm est réduit au rapport $2/5$. Donner les trois nouvelles longueurs.",r"On multiplie chaque côté par $2/5$. Les nouvelles longueurs sont $\res2$ cm, $\res{2{,}8}$ cm et $\res{3{,}2}$ cm. Les angles restent les mêmes ; les longueurs changent.","Appliquer le rapport à chaque côté.","assert [a*Rational(2,5) for a in [5,7,8]]==[2,Rational('2.8'),Rational('3.2')]",figure='trans-08'),
E('Une aire agrandie',r"Une figure d’aire 18 cm$^2$ est agrandie au rapport 3. Quelle est sa nouvelle aire ?",r"Le rapport des longueurs est 3, donc celui des aires est $3^2=9$. La nouvelle aire vaut $18\times9=\res{162\ \mathrm{cm}^2}$, et non 54.","Mettre au carré le rapport des longueurs.","assert 18*3**2==162",figure='trans-09'),
E('Un volume réduit',r"Un pavé droit de volume 240 cm$^3$ est réduit au rapport $1/2$. Quel est le volume image ?",r"Toutes les dimensions sont divisées par 2 ; le volume est donc multiplié par $(1/2)^3=1/8$. Il vaut $240/8=\res{30\ \mathrm{cm}^3}$.","Élever le rapport au cube pour un volume.","assert 240*Rational(1,2)**3==30",figure='trans-10'),
E('Retrouver le rapport',r"Deux figures sont l’une un agrandissement de l’autre. Leurs aires sont 20 et 45 cm$^2$. Trouver le rapport d’agrandissement et l’image d’un côté de 8 cm.",r"$k^2=45/20=2{,}25$, donc $k=\sqrt{2{,}25}=\res{1{,}5}$. Le côté devient $8\times1{,}5=\res{12}$ cm. On choisit le rapport positif.","Prendre la racine positive du rapport d’aires.","assert sqrt(Rational(45,20))==Rational('1.5') and 8*Rational('1.5')==12",figure='trans-11'),
E('Un pavé à l’échelle',r"Un pavé droit mesure 12, 8 et 6 cm. On réduit toutes ses dimensions au tiers. Donner dimensions, aire de la face 12 par 8 et volume après réduction.",r"Les dimensions deviennent $\res{4,\ 8/3,\ 2}$ cm. La face a une aire de $(12\times8)/9=\res{32/3}$ cm$^2$. Le volume devient $(12\times8\times6)/27=\res{64/3}$ cm$^3$. Les facteurs sont respectivement $1/3$, $1/9$ et $1/27$.","Distinguer longueur, aire et volume.","assert Rational(12*8,9)==Rational(32,3) and Rational(12*8*6,27)==Rational(64,3)",figure='trans-12'),
E('Deux déplacements',r"On déplace un point de 5 carreaux à droite et 2 en haut, puis de 3 à gauche et 4 en haut. Quel glissement unique donne le même résultat ?",r"Horizontalement : $5-3=2$ carreaux à droite. Verticalement : $2+4=6$ vers le haut. Le glissement total est donc $\res{2\text{ à droite et }6\text{ en haut}}$. Les déplacements s’additionnent avec leurs sens.","Additionner séparément les déplacements sur chaque axe.","assert (5-3,2+4)==(2,6)",figure='trans-13'),
E('Le bon coefficient de peinture',r"Une maquette de surface extérieure 0,8 m$^2$ est agrandie en multipliant toutes ses longueurs par 2,5. La peinture couvre 4 m$^2$ par litre. Quelle quantité théorique faut-il pour la nouvelle surface ?",r"La surface est multipliée par $2{,}5^2=6{,}25$, donc elle vaut $0{,}8\times6{,}25=5$ m$^2$. La peinture nécessaire est $5/4=\res{1{,}25\ \mathrm L}$ dans le modèle sans perte. Utiliser seulement 2,5 comme facteur d’aire serait faux.","Calculer la nouvelle aire avant la quantité.","assert Rational('.8')*Rational('2.5')**2/4==Rational('1.25')",figure='trans-14'),
E('Un pavage par translations',r"Un motif carré de côté 2 cm est répété sans trou ni chevauchement sur 6 colonnes et 4 lignes. Combien de motifs utilise-t-on ? Donner l’aire totale et un déplacement permettant de passer d’un motif au motif situé deux colonnes à droite et une ligne au-dessus.",r"Il y a $6\times4=\res{24}$ motifs, chacun d’aire 4 cm$^2$. L’aire totale vaut $\res{96\ \mathrm{cm}^2}$. Le déplacement demandé est de $\res4$ cm à droite et $\res2$ cm vers le haut. Les translations conservent la taille du motif.","Compter les copies et convertir le déplacement en longueurs.","assert 6*4==24 and 24*2**2==96",figure='trans-15')
],reperes=['Construire par translation','Conservation et parallélogrammes','Frises et pavages','Rapports de longueurs, d’aires et de volumes'],deco='geometrie')

chapitre(17,'solides','Espace, pyramides et cônes','4 · Géométrie et espace',
'Perspective · Patron · Repérage · Volume',
['Lire et produire des représentations de solides.','Se repérer par abscisse, ordonnée et altitude.','Calculer les volumes d’une pyramide et d’un cône.'],
['Aires, volumes du pavé et du cylindre, Pythagore.'],[
r'''\essSection{1}{Voir et représenter}
\begin{definition}Une pyramide a une base polygonale et des faces latérales triangulaires réunies en un sommet. Un cône de révolution est obtenu par la rotation d’un triangle rectangle autour d’un côté de l’angle droit. Sa base est un disque ; une génératrice relie le sommet au cercle de base.\end{definition}
\begin{savoirfaire}[Perspective et patron]La perspective cavalière indique les arêtes cachées en pointillés ; elle ne conserve pas toutes les longueurs ni tous les angles. Un patron est une figure plane qui permet de reconstituer le solide par pliage. Les longueurs qui se rejoignent doivent coïncider. Pour un cône, le bord courbe du secteur latéral a la longueur du cercle de base.\end{savoirfaire}
@FIG:cours-solides@
\begin{definition}Dans un pavé muni d’un repère, un point a trois coordonnées $(x;y;z)$ : abscisse, ordonnée, altitude. Lire dans l’ordre des trois axes, pas dans l’ordre apparent des arêtes sur la feuille.\end{definition}''',
r'''\essSection{2}{Des volumes liés à une base}
\begin{propriete}Pour une pyramide, $V=\frac13\mathcal B h$, où $\mathcal B$ est l’aire de la base et $h$ la hauteur perpendiculaire à son plan. Pour un cône de rayon $r$, $V=\frac13\pi r^2h$. Un prisme ou cylindre de même base et de même hauteur a un volume trois fois plus grand.\end{propriete}
\begin{exemple}Une pyramide de base carrée de côté 6 cm et de hauteur 8 cm a pour volume $(1/3)\times36\times8=96$ cm$^3$. Un cône de rayon 3 cm et de hauteur 5 cm a pour volume $(1/3)\pi\times9\times5=15\pi$ cm$^3$.\end{exemple}
\begin{savoirfaire}[Choisir les bonnes données]Calculer l’aire de base avant le volume. La hauteur est perpendiculaire à la base : ce n’est ni une arête inclinée ni une génératrice. Si les unités diffèrent, convertir avant de les multiplier. Une aire en cm$^2$ multipliée par une hauteur en cm donne un volume en cm$^3$.\end{savoirfaire}
\begin{attention}La perspective peut écraser une hauteur ou un angle droit. Se fier aux données, aux codages et aux noms, sans mesurer le dessin. Pour un cône, le diamètre doit être divisé par 2 avant d’utiliser le rayon dans $\pi r^2$.\end{attention}'''],[
E('Nommer les éléments',r"Une pyramide SABCD a une base carrée ABCD. Nommer son sommet, sa base et le nombre de ses faces latérales.",r"Le sommet est $\res S$, la base est le carré $\res{ABCD}$. Il y a $\res4$ faces latérales triangulaires : SAB, SBC, SCD et SDA. Avec la base, le solide a cinq faces.","Distinguer base et faces latérales.","assert len(['SAB','SBC','SCD','SDA'])==4",figure='sol-01'),
E('Une pyramide à base carrée',r"Une pyramide a une base carrée de côté 6 cm et une hauteur de 8 cm. Calculer son volume.",r"L’aire de la base vaut $6^2=36$ cm$^2$. Le volume est $V=36\times8/3=\res{96\ \mathrm{cm}^3}$. La hauteur donnée est perpendiculaire à la base.","Calculer d’abord l’aire de base.","assert Rational(6**2*8,3)==96",figure='sol-02'),
E('Un cône',r"Un cône a pour rayon 3 cm et pour hauteur 5 cm. Donner son volume exact puis au dixième de cm$^3$.",r"$V=\pi\times3^2\times5/3=\res{15\pi\ \mathrm{cm}^3}$. Numériquement, $V\approx\res{47{,}1\ \mathrm{cm}^3}$. Garder $\pi$ pour la valeur exacte.","Appliquer la formule avec le rayon.","assert round(float(15*pi),1)==47.1",figure='sol-03'),
E('Du diamètre au rayon',r"Un cône a une base de diamètre 8 cm et une hauteur de 9 cm. Calculer son volume exact.",r"Le rayon vaut $8/2=4$ cm. Donc $V=\pi\times4^2\times9/3=\res{48\pi\ \mathrm{cm}^3}$. Utiliser 8 comme rayon multiplierait l’aire de base par 4.","Diviser le diamètre par deux.","assert simplify(pi*Rational(8,2)**2*Rational(9,3))==48*pi",figure='sol-04'),
E('Lire trois coordonnées',r"Le pavé a pour dimensions 6, 4 et 3 unités, selon les axes $x$, $y$, $z$. Donner les coordonnées du sommet G opposé à O et de H au-dessus du point de coordonnées (0;4;0).",r"Le sommet opposé utilise les trois dimensions : $\res{G(6;4;3)}$. H a la même abscisse 0 et la même ordonnée 4 que son pied, avec altitude 3 : $\res{H(0;4;3)}$.","Suivre les axes dans l’ordre abscisse, ordonnée, altitude.","assert (6,4,3)[2]==3 and (0,4,3)[0]==0",figure='sol-05'),
E('Placer un point',r"Dans le pavé repéré, placer M(2;3;1). Décrire les trois déplacements depuis O.",r"Depuis O, avancer de 2 unités selon $x$, puis de 3 selon $y$, puis monter d’une unité selon $z$. Les pointillés de construction se rencontrent en $\res{M(2;3;1)}$, à l’intérieur du pavé.","Reporter les trois coordonnées dans leur direction.","assert 0<2<6 and 0<3<4 and 0<1<3",figure='sol-06'),
E('Base triangulaire',r"Une pyramide a pour base un triangle de côté 8 cm et de hauteur associée 3 cm. La hauteur de la pyramide est 10 cm. Calculer son volume.",r"L’aire de base est $8\times3/2=12$ cm$^2$. La hauteur du solide vaut 10 cm, différente de la hauteur du triangle de base. $V=12\times10/3=\res{40\ \mathrm{cm}^3}$.","Distinguer hauteur de base et hauteur du solide.","assert Rational(8*3,2)*Rational(10,3)==40",figure='sol-07'),
E('Retrouver une hauteur',r"Une pyramide a un volume de 150 cm$^3$ et une aire de base de 45 cm$^2$. Déterminer sa hauteur.",r"$150=45h/3=15h$. Donc $h=150/15=\res{10\ \mathrm{cm}}$. La formule donne une longueur car on divise un volume par une aire.","Isoler la hauteur dans la formule.","assert Rational(3*150,45)==10",figure='sol-08'),
E('Un patron de pyramide',r"On veut un patron de pyramide de base carrée de côté 4 cm, dont les quatre arêtes latérales mesurent 5 cm. Décrire puis construire un patron.",r"Tracer un carré de côté 4 cm. À l’extérieur, construire sur chacun de ses côtés un triangle isocèle de côtés 5, 5 et 4 cm. Les quatre bases des triangles coïncident avec les côtés du carré ; leurs sommets se rejoindront au pliage. Le patron comporte un carré et quatre triangles.","Faire correspondre les côtés qui seront assemblés.","assert 5+5>4 and len(range(4))==4",figure='sol-09'),
E('Un patron de cône',r"Un cône a pour rayon de base 3 cm et pour génératrice 5 cm. Le représenter en perspective, puis compléter son patron : un disque de base et un secteur de rayon 5 cm dont on déterminera l’angle au centre.",r"Pour la perspective, tracer une ellipse pour la base, placer le sommet au-dessus du centre et le relier au bord ; représenter en pointillés les parties cachées. Le bord courbe du secteur doit mesurer le périmètre de base $2\pi\times3=6\pi$ cm. Le cercle de rayon 5 a pour périmètre $10\pi$ ; il faut donc $6/10$ de tour, soit $\res{216^\circ}$. Ajouter le disque de rayon 3 cm. La génératrice, et non la hauteur, est le rayon du secteur.","Relier la perspective au patron par les longueurs.","assert simplify((2*pi*3)/(2*pi*5)*360)==216",figure='sol-10'),
E('Une génératrice calculée',r"Un cône a une hauteur de 12 cm et un rayon de 5 cm. Calculer sa génératrice puis son volume exact.",r"La hauteur, le rayon et la génératrice forment un triangle rectangle. La génératrice vaut $\sqrt{12^2+5^2}=\res{13}$ cm. Le volume est $\pi\times5^2\times12/3=\res{100\pi\ \mathrm{cm}^3}$. La génératrice ne remplace pas la hauteur dans cette formule.","Séparer le triangle de section et la formule du volume.","assert sqrt(12**2+5**2)==13 and Rational(25*12,3)==100",figure='sol-11'),
E('Comparer un cylindre et un cône',r"Un cône et un cylindre ont la même base de rayon 4 cm et la même hauteur de 6 cm. Donner leurs volumes et leur différence.",r"Le cylindre a pour volume $\pi\times16\times6=\res{96\pi}$ cm$^3$. Le cône a le tiers, soit $\res{32\pi}$ cm$^3$. Leur différence vaut $\res{64\pi\ \mathrm{cm}^3}$.","Utiliser la base et la hauteur communes.","assert 16*6==96 and Rational(16*6,3)==32 and 96-32==64",figure='sol-12'),
E('Deux unités',r"Un réservoir conique a un rayon de 40 cm et une hauteur de 1,2 m. Donner sa capacité en litres au dixième.",r"On choisit les dm : $r=4$ dm et $h=12$ dm. $V=\pi\times4^2\times12/3=64\pi$ dm$^3$, donc $64\pi$ L, soit environ $\res{201{,}1\ \mathrm L}$. Les unités sont unifiées avant le calcul.","Choisir les décimètres pour obtenir directement des litres.","assert round(float(64*pi),1)==201.1",figure='sol-13'),
E('Un assemblage',r"Un solide est formé d’un pavé de 8 cm sur 6 cm sur 4 cm, surmonté d’une pyramide dont la base est le rectangle supérieur du pavé et dont la hauteur vaut 3 cm. Calculer le volume total.",r"Le pavé a pour volume $8\times6\times4=192$ cm$^3$. La pyramide a pour volume $(8\times6)\times3/3=48$ cm$^3$. Les deux intérieurs ne se chevauchent pas : le total vaut $\res{240\ \mathrm{cm}^3}$.","Additionner les volumes des deux parties.","assert 8*6*4+Rational(8*6*3,3)==240",figure='sol-14'),
E('Un remplissage partiel',r"Un récipient conique de rayon 6 cm et de hauteur 10 cm est rempli aux trois quarts de sa capacité. Calculer le volume d’eau exact en cm$^3$, puis en mL au dixième. Peut-on en déduire une hauteur d’eau de 7,5 cm ?",r"La capacité vaut $\pi\times36\times10/3=120\pi$ cm$^3$. L’eau occupe $3/4$ de cette capacité, soit $\res{90\pi\ \mathrm{cm}^3}\approx\res{282{,}7\ \mathrm{mL}}$. On ne peut pas conclure à une hauteur de 7,5 cm : la section du cône change avec la hauteur, donc volume et hauteur ne sont pas proportionnels.","Appliquer la fraction au volume, sans la transférer à la hauteur.","assert Rational(3,4)*120*pi==90*pi and round(float(90*pi),1)==282.7",figure='sol-15')
],reperes=['Pyramides, cônes et perspective','Repérage dans un pavé droit','Patrons de pyramides et de cônes','Volumes, unités et assemblages'],deco='espace')

chapitre(18,'programmation','Algorithmique et programmation par blocs','5 · Programmer et réinvestir',
'Séquences · Variables · Conditions · Boucles · Événements',
['Lire, compléter et expliquer un script.','Utiliser variables, conditions et répétitions.','Programmer des constructions et des réactions à un événement.'],
['Calcul littéral, angles et repérage.'],[
r'''\essSection{1}{Décrire une suite d’actions}
\begin{definition}Un algorithme est une suite précise d’instructions permettant une tâche. Un programme le traduit dans un langage. Une variable est une mémoire nommée : « mettre x à 3 » remplace son contenu par 3 ; « ajouter 2 à x » augmente son contenu actuel de 2.\end{definition}
\begin{savoirfaire}[Lire un script]Repérer l’événement de départ, puis suivre les blocs dans l’ordre. Construire un tableau des valeurs des variables. Dans une boucle « répéter n fois », toutes les instructions à l’intérieur sont reprises à chaque tour. Les indentations et lignes « fin » du livre indiquent leur appartenance.\end{savoirfaire}
@FIG:script-01@
\begin{attention}Une instruction qui modifie une variable utilise sa valeur au moment où elle est exécutée. Permuter deux blocs peut changer le résultat. On initialise les variables avant de les faire évoluer, pour ne pas dépendre d’une ancienne exécution.\end{attention}''',
r'''\essSection{2}{Choisir, répéter et réagir}
\begin{definition}Une condition est vraie ou fausse. Le bloc « si … alors … sinon » choisit la branche correspondante. Un événement, comme le clic sur le drapeau, une touche pressée ou un message reçu, déclenche un script. Une condition de contact permet à un lutin de réagir à un autre.\end{definition}
\begin{exemple}Pour tracer un carré, stylo baissé, répéter 4 fois « avancer de c ; tourner de $90^\circ$ ». Pour un triangle équilatéral, le lutin tourne de $120^\circ$, angle extérieur, et non de $60^\circ$. On indique ici le sens de rotation.\end{exemple}
\begin{savoirfaire}[Mettre au point]Tester des entrées habituelles et des cas limites, comme une valeur juste égale au seuil d’une condition. Vérifier le nombre de tours et la place de l’affichage. Pour un dessin, préciser le point initial, l’orientation et l’état du stylo. Le résultat observé doit être expliqué par les instructions.\end{savoirfaire}
\begin{attention}Les niveaux 1 et 2 des attendus sont travaillés ici : séquences, conditions, répétitions, événements, variables et interactions simples. Le défi final propose une recherche supplémentaire ; les scripts parallèles complexes et les boucles « jusqu’à » ne sont pas exigés pour ce parcours.\end{attention}'''],[
E('Suivre les valeurs',r"Exécuter le script. Quelle valeur affiche-t-il ?",r"x prend d’abord 4, puis $4+3=7$, puis $7\times2=14$. L’affichage final est donc $\res{14}$. L’ordre des blocs importe.","Écrire la valeur de x après chaque modification.","assert (4+3)*2==14",figure='script-01'),
E('Une entrée utilisateur',r"Le script demande un nombre x. Donner le résultat pour 5, puis exprimer le résultat pour une entrée quelconque.",r"Pour 5, $(5-2)\times4=\res{12}$. Pour une entrée $x$, le programme donne $\res{4(x-2)=4x-8}$. Le dernier bloc utilise la valeur déjà diminuée de 2.","Traduire la séquence dans son ordre.","assert (5-2)*4==12 and expand(4*(x-2))==4*x-8",figure='script-02'),
E('Une boucle d’ajouts',r"Exécuter la boucle du script et donner l’affichage.",r"On part de x = 0 et l’on ajoute 5 à chacun des trois tours : 5, 10, 15. Après la boucle, l’affichage est $\res{15}$. Le bloc « dire » est placé une seule fois après la répétition.","Compter les tours et situer l’affichage.","assert 0+3*5==15",figure='script-03'),
E('Une condition au seuil',r"Le script classe un nombre avec le test x $\ge10$. Donner les messages pour x = 9 et x = 10.",r"Pour 9, le test est faux : le message est « petit ». Pour 10, le test est vrai car l’égalité est admise : le message est « grand ». Le cas x = 10 vérifie la frontière de la condition.","Tester aussi la valeur égale au seuil.","assert not 9>=10 and 10>=10",figure='script-04'),
E('Un produit répété',r"Le script part de x = 3 et double x quatre fois. Donner les valeurs successives et l’affichage final.",r"Les valeurs après les tours sont 6, 12, 24 et 48. L’affichage est $\res{48}$. On peut écrire $3\times2^4=48$ ; ajouter quatre fois 2 décrirait un autre programme.","Distinguer répétition d’un produit et répétition d’une somme.","assert 3*2**4==48",figure='script-05'),
E('Une somme construite',r"Le script utilise s et n. Donner les valeurs de s après chaque tour et expliquer le résultat.",r"Au départ s = 0 et n = 1. Les quatre tours ajoutent 1, 2, 3 puis 4 : s vaut successivement 1, 3, 6, 10. Le résultat est $\res{10}$. L’ajout à s précède l’augmentation de n.","Suivre les deux variables dans un tableau.","assert sum(range(1,5))==10",figure='script-06'),
E('Tracer un carré',r"Le lutin part de (0;0), orienté vers la droite, stylo baissé. Décrire la figure et la position finale du script.",r"Il trace quatre segments de 30 pixels, avec un quart de tour antihoraire entre eux. La figure est un carré de côté $\res{30}$ pixels. Il revient en $\res{(0;0)}$ et retrouve sa direction initiale après un tour complet.","Additionner les angles de rotation.","assert 4*90==360",figure='script-07'),
E('Tracer un rectangle',r"Décrire le dessin du script, avec le même départ et le stylo baissé. Donner son périmètre.",r"Chaque tour de boucle trace un côté de 50 puis un côté de 20 pixels avec les quarts de tour adaptés. Deux répétitions ferment un rectangle de 50 par 20 pixels. Le périmètre vaut $2(50+20)=\res{140}$ pixels.","Lire tout le contenu répété.","assert 2*(50+20)==140 and 2*2*90==360",figure='script-08'),
E('Deux tests de parité',r"Le bloc « reste de x divisé par 2 » est nul si x est pair. Que dit le script pour 18 et pour 19 ?",r"18 a un reste nul dans la division par 2 : le script dit « pair ». 19 a pour reste 1 : il dit « impair ». Les deux branches couvrent ici tous les entiers.","Relier le reste au test de la condition.","assert 18%2==0 and 19%2==1",figure='script-09'),
E('Utiliser une touche',r"Le script est déclenché par la touche espace et ajoute 1 à score. score vaut 0 avant les appuis et n’est pas réinitialisé par ce script. Quelle valeur obtient-on après cinq appuis successifs ?",r"Chaque événement « espace pressée » lance un seul ajout. Après cinq appuis, score vaut $\res5$. Mettre score à 0 dans ce même script avant l’ajout donnerait toujours 1 : l’initialisation doit se faire au début de la partie.","Distinguer lancement de partie et événement répété.","assert 0+5==5",figure='script-10'),
E('Un triangle équilatéral',r"Le lutin avance de 40 pixels et tourne de $120^\circ$, trois fois. Il part orienté à droite, stylo baissé. Justifier la figure et expliquer pourquoi $60^\circ$ ne convient pas.",r"Les trois côtés mesurent 40 et les trois rotations extérieures font $3\times120=360^\circ$. La figure est un triangle équilatéral. L’angle intérieur vaut $180-120=60^\circ$. Tourner seulement de $60^\circ$ ne fermerait pas le triangle en trois côtés.","Distinguer l’angle intérieur de l’angle de rotation.","assert 3*120==360 and 180-120==60",figure='script-11'),
E('Une interaction simple',r"Le script teste si le lutin touche le lutin Guide. Quel message affiche-t-il selon que le contact est présent ou absent ? Pourquoi faut-il relancer ce script pour tester un nouveau contact ?",r"Si le contact est présent au moment du test, il dit « Bonjour ! ». Sinon il dit « Je cherche ». Le script ne contient ni répétition ni autre nouveau déclenchement : il effectue un seul test à chaque clic sur le drapeau. Une réaction permanente demanderait de répéter le test.","Repérer le moment où la condition est évaluée.","assert bool(1) and not bool(0)",figure='script-12'),
E('Une dimension saisie',r"Le script demande une longueur positive c puis trace une figure. Donner le résultat pour c = 25 et exprimer la longueur totale tracée en fonction de c.",r"La boucle trace un carré de côté c. Pour c = 25, la longueur totale vaut $4\times25=\res{100}$ pixels. En général, elle vaut $\res{4c}$ pixels. Il faut une valeur positive pour la longueur demandée.","Relier variable d’entrée et mesure géométrique.","assert 4*25==100",figure='script-13'),
E('Chercher une erreur de boucle',r"Un script met s à 0 à l’intérieur de la boucle, puis ajoute 3 à s, quatre fois. Il affiche s après la boucle. Expliquer le résultat et corriger pour obtenir 12.",r"À chaque tour, s redevient 0 puis vaut 3 : l’affichage est donc $\res3$. Pour accumuler quatre ajouts, déplacer « mettre s à 0 » avant la boucle, puis répéter seulement l’ajout. On obtient $0+4\times3=\res{12}$.","Conserver la mémoire d’un tour au suivant.","assert 0+3==3 and 4*3==12",figure='script-14'),
E('Concevoir et vérifier',r"Créer un script qui demande x, calcule $3x+5$, puis dit « positif » si le résultat est strictement positif et « nul ou négatif » sinon. Tester les entrées 2, $-2$ et $-5/3$.",r"Demander x ; mettre y à $3x+5$ ; si y $>0$, dire « positif », sinon dire « nul ou négatif ». Pour 2, y = 11 : positif. Pour $-2$, y = $-1$ : nul ou négatif. Pour $-5/3$, y = 0 : même seconde branche. Le troisième test vérifie l’égalité au seuil.","Tester une valeur de chaque côté du seuil et le seuil lui-même.","assert [3*a+5 for a in [2,-2,Rational(-5,3)]]==[11,-1,0]",figure='script-15')
],reperes=['Séquences, entrées et variables','Conditions et cas limites','Boucles et constructions géométriques','Événements, interaction et mise au point'],deco='algorithmique')
